-- To restore a policy: DROP POLICY IF EXISTS <name> ON public.<table>; then run its CREATE line below.

CREATE POLICY "Allow public all banners" ON public.banners AS PERMISSIVE FOR ALL TO public USING (true) WITH CHECK (true);
CREATE POLICY owner_only_del ON public.banners AS RESTRICTIVE FOR DELETE TO public USING (is_store_admin());
CREATE POLICY owner_only_ins ON public.banners AS RESTRICTIVE FOR INSERT TO public WITH CHECK (is_store_admin());
CREATE POLICY owner_only_upd ON public.banners AS RESTRICTIVE FOR UPDATE TO public USING (is_store_admin());
CREATE POLICY store_isolation ON public.banners AS RESTRICTIVE FOR ALL TO public USING ((store_id = current_store_id())) WITH CHECK ((store_id = current_store_id()));
