-- Triggers
CREATE TRIGGER order_item_store_match BEFORE INSERT OR UPDATE ON public.order_items FOR EACH ROW EXECUTE FUNCTION guard_order_item_store();
CREATE TRIGGER protect_payment_receipts BEFORE INSERT OR UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION guard_payment_receipts();
CREATE TRIGGER protect_profile_permissions BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION guard_profile_permissions();
CREATE TRIGGER role_updated BEFORE UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
CREATE TRIGGER sync_profile_permissions AFTER INSERT OR UPDATE OF role, store_id ON public.profiles FOR EACH ROW EXECUTE FUNCTION sync_profile_permissions();
CREATE TRIGGER update_store_payment_gateways_updated_at BEFORE UPDATE ON public.store_payment_gateways FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
